{
  "text": "Xin chào, đây là thử nghiệm tổng hợp giọng tự động.",
  "language": "Vietnamese",
  "num_step": 16
}

{
  "text": "Bản clone qua API bằng voice_id đã đăng ký.",
  "voice_id": "{{voice_id}}",
  "language": "Vietnamese",
  "num_step": 16
}

{
  "text": "Clone trực tiếp từ audio mẫu gửi kèm.",
  "ref_audio": "<BASE64_AUDIO>",
  "ref_text": "Transcript của audio mẫu (bỏ trống để Whisper tự nhận).",
  "language": "Vietnamese"
}

{
  "text": "This is a test of voice design.",
  "instruct": "female, young adult, high pitch, british accent",
  "language": "English"
}

{
  "text": "Hơn 155.000 doanh nghiệp dùng Zalo, chiếm 85% năm 2024.",
  "voice_id": "{{voice_id}}",
  "normalize": true,
  "response_format": "mp3"
}

{
  "model": "k2-fsa/OmniVoice",
  "input": "This is a designed voice.",
  "voice": "female, british accent",
  "response_format": "wav"
}
